saleor.core-unit.saleor.graphql.checkout.tests.test_checkout_line_problems.test_query_checkouts_calculate_flat_taxes_when_variant_not_available[
{
  checkouts(first: 10) {
    edges {
      node {
        lines {
          problems {
            __typename
            ... on CheckoutLineProblemVariantNotAvailable {
              line {
                totalPrice {
                  gross {
                    amount
                  }
                }
              }
            }
            ... on CheckoutLineProblemInsufficientStock {
              line {
                totalPrice {
                  gross {
                    amount
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
]

